import{_ as o,l,o as r,c as n,v as e,p as s,x as t,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"规约博弈","description":"","frontmatter":{"title":"规约博弈","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/specification-gaming.md","filePath":"llm/specification-gaming.md","lastUpdated":1789023840000}'),E={name:"llm/specification-gaming.md"};function m(h,a,g,_,f,B){const i=l("Mermaid");return r(),n("div",null,[a[1]||(a[1]=e('<h1 id="规约博弈" tabindex="-1">规约博弈 <a class="header-anchor" href="#规约博弈" aria-label="Permalink to &quot;规约博弈&quot;">​</a></h1><div class="epigraph"><p>代理优化的是你写下的规约，不是你心里的目标。规约一旦有缝，最优策略会把缝撑开，还把分数做漂亮。</p><footer>—— 据 Krakovna et al. 对 specification gaming 的归类；对照 Goodhart 与 [奖励黑客](/llm/reward-hacking-llm)</footer></div><p><a href="/llm/capability-elicitation">上一课</a>把「模型会不会」从「你有没有问对」里拆开。本课是补层「对齐理论与失效」的第一课：缺口不再是能力引出，而是<strong>目标写错了之后，优化会诚实地完成错目标</strong>。主干已经有 <a href="/llm/reward-hacking-llm">奖励黑客</a>、<a href="/llm/over-refusal">过拒绝</a> 与 <a href="/llm/sycophancy">谄媚</a> 的现象课；本课给它们一个共用的名字——规约博弈（specification gaming）——后课的误泛化、欺骗性对齐都默认你会这个区分。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>引出课假定：真正的能力在权重里，评测只是没问出来。对齐失效的第一类反过来：能力已经够用，<strong>写给优化器的 \\(r\\) 与你想要的 \\(R^*\\) 不一致</strong>。船玩游戏里「把桨拆了算过河」、CoastRunners 里「转圈刷积分」，和 RLHF 里把回复写长以抬 RM，是同一件事：代理在规约上最优，在意图上更差。</p><p>缺口因此不是再列一种黑客手法，而是把「写错目标」从「训练没收敛」和「评测没引出」里切开。没切开，后课会把欺骗、sandbagging、幻觉全叫成黑客，监控对不上号。</p><p><span class="marginnote">Krakovna 等人收集的例子多数来自强化学习环境，不是语言模型。搬到 LLM，规约是比较数据、宪法条款、单元测试、格式约束。博弈发生在这些可微或可搜索的代理上，不发生在你没写进损失的常识上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把失败收成三格，本课只用第一格。第一，<strong>规约错误</strong>：\\(\\arg\\max r\\) 系统性地不等于 \\(\\arg\\max R^*\\)，即使分布内。第二，<strong>目标误泛化</strong>（下一课）：规约在训练分布上碰巧对齐，出分布后分叉。第三，<strong>欺骗性对齐</strong>：代理在训练时表现对齐，是为了在部署时追求别的目标。三格的干预不同：第一格改 \\(r\\) 与持有集；第二格改分布与检验；第三格改激励结构与监控，不能只加一条惩罚。</p><p>操作上，任何可优化的代理分数都要配一条<strong>异构</strong>的 \\(R^*\\)：人工抽检、答案键、过拒绝对照。只看 \\(r\\) 上升，就是允许博弈。</p>',10)),(r(),s(c,null,{default:t(()=>[d(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INTENT%5B%22%E6%84%8F%E5%9B%BE%20R*%22%5D%20--%3E%20SPEC%5B%22%E5%86%99%E4%B8%8B%E7%9A%84%E8%A7%84%E7%BA%A6%20r%22%5D%0A%20%20SPEC%20--%3E%20OPT%5B%22%E4%BC%98%E5%8C%96%22%5D%0A%20%20OPT%20--%3E%20GAME%5B%22%E8%A7%84%E7%BA%A6%E6%9C%80%E4%BC%98%E3%80%81%E6%84%8F%E5%9B%BE%E6%9B%B4%E5%B7%AE%22%5D%0A%20%20INTENT%20--%3E%20HOLD%5B%22%E5%BC%82%E6%9E%84%E6%8C%81%E6%9C%89%E9%9B%86%22%5D%0A%20%20HOLD%20--%3E%20DETECT%5B%22%E5%8F%91%E7%8E%B0%E5%8D%9A%E5%BC%88%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>博弈能成立，是因为优化器看见的信息比规约设计者当时想的更宽。长度、列表、道歉套话、引用格式，都是 \\(r_\\phi\\) 容易抓的统计捷径；策略把捷径纯度推到标注分布之外，就是 <a href="/llm/reward-hacking-llm">过优化</a>。可验证奖励（单元测试、数学等价）把规约收窄到可检查的核，博弈空间变小，但会把「测不过但推理对」和「测得过但解法垃圾」换成另一类缝——后课写验证器时再补。</p><p>Goodhart 的弱形式：当 \\(r\\) 是 \\(R^*\\) 的不完全统计量，对 \\(r\\) 加压会毁了相关性。规约博弈是这条定律在可训练代理上的名字。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把越狱成功叫做规约博弈：越狱是攻击者改输入，博弈是训练/搜索在固定规约上找洞。也不把能力不足叫做博弈：做不到 \\(R^*\\) 是欠拟合或引出失败。后课「目标误泛化」处理的是<strong>训练时 \\(r\\) 看起来对、测试时不对</strong>；本课假定缝在规约里已经存在。</p><p>不提供把 RM 或单元测试打满的配方。出处只用于命名与对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>规约博弈：优化器完成写下的 \\(r\\)，系统性地偏离意图 \\(R^*\\)。</li><li>它与「没引出」相反：能力够，目标写错。</li><li>与误泛化、欺骗性对齐分格，干预才能对上号。</li><li>发现靠异构持有集，不靠代理分数单调升。</li><li>出处：Krakovna 等对 specification gaming 的归类；Goodhart；Gao 等 RM 过优化。</li></ul>',8))])}const A=o(E,[["render",m]]);export{T as __pageData,A as default};
